-- ============================================================================
-- 05_timss.sql   |   Exam type: الرياضيات والعلوم  (code = 'TIMSS')
-- ----------------------------------------------------------------------------
-- 5 sections x 20 questions x 4 choices (1 correct) = 100 questions / 400 choices
-- Content is Arabic.
--
-- Target: PostgreSQL. Tables per prisma/schema.prisma
--   exam_types (id uuid, name text, code varchar(100) UNIQUE)
--   sections   (id uuid, name text, exam_type_id uuid -> exam_types.id)
--   questions  (id uuid, content text, explanation text, created_at, section_id uuid)
--   choices    (id uuid, content text, is_correct bool, question_id uuid)
--
-- IDEMPOTENT: safe to re-run. No hard-coded UUIDs, so it works alongside rows
-- already created by the Prisma seeder (src/seeds/seed.ts). Rows are matched on
-- natural keys (exam_types.code, sections.name, questions.content, choices.content).
--
-- NOTE: the mobile app selects exam types and sections by NAME substring, not by
-- code -- see src/app/{verbal,quantitative,achievement,step}.tsx. Changing a
-- name below can make a section stop showing up on its screen.
--
-- Run:  psql "$DATABASE_URL" -f 05_timss.sql
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1) EXAM TYPE
-- ----------------------------------------------------------------------------
-- NOTE: every id is supplied explicitly. prisma/schema.prisma declares the ids as
-- @default(uuid()), which Prisma resolves in the client, so the DDL has no column
-- DEFAULT and a raw INSERT that omits id fails with SQLSTATE 23502.
-- gen_random_uuid() is built in from PostgreSQL 13 on, so no extension is needed.
INSERT INTO exam_types (id, name, code)
SELECT gen_random_uuid(), v.name, v.code
FROM (VALUES ('الرياضيات والعلوم', 'TIMSS')) AS v(name, code)
WHERE NOT EXISTS (
  SELECT 1 FROM exam_types et WHERE et.code = v.code
);

-- The exam type was renamed. A database seeded before the rename still has
-- the old name (the INSERT above is guarded on code, so it inserts nothing).
-- This corrects it, matching only the known old names so it never overwrites a
-- name an admin has since customised.
UPDATE exam_types
SET name = 'الرياضيات والعلوم'
WHERE code = 'TIMSS'
  AND name IN ('تميس');


-- ----------------------------------------------------------------------------
-- 2) SECTIONS
-- ----------------------------------------------------------------------------
INSERT INTO sections (id, name, exam_type_id)
SELECT gen_random_uuid(), v.name, et.id
FROM (VALUES
  ('الرياضيات', 1),
  ('العلوم'   , 2),
  ('البيانات' , 3),
  ('الدراسة'  , 4),
  ('القراءة'  , 5)
) AS v(name, ord)
JOIN exam_types et ON et.code = 'TIMSS'
WHERE NOT EXISTS (
  SELECT 1 FROM sections s
  WHERE s.exam_type_id = et.id AND s.name = v.name
);

-- ============================================================================
-- 3) QUESTIONS + CHOICES
--    Repeated per section. `sec` resolves the section id from its natural key.
-- ============================================================================

-- ---------------------------------------------------------------- الرياضيات ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'TIMSS' AND s.name = 'الرياضيات'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('ناتج ٣ × ٨ يساوي:'                                    , '٣ × ٨ = ٢٤.'                                               , 1),
  ('ناتج ٤٨ ÷ ٦ يساوي:'                                   , '٤٨ ÷ ٦ = ٨، لأن ٦ × ٨ = ٤٨.'                               , 2),
  ('ناتج ٢ × ٣ + ٤ يساوي:'                                , 'نضرب أولا: ٢ × ٣ = ٦، ثم نجمع: ٦ + ٤ = ١٠.'                , 3),
  ('قيمة ٥٠ − ١٨ تساوي:'                                  , 'نطرح: ٥٠ − ١٨ = ٣٢.'                                       , 4),
  ('قيمة ٧ × ٧ تساوي:'                                    , '٧ × ٧ = ٤٩.'                                               , 5),
  ('ناتج (١٦ ÷ ٢) × ٣ يساوي:'                             , 'نقسم أولا: ١٦ ÷ ٢ = ٨، ثم نضرب: ٨ × ٣ = ٢٤.'               , 6),
  ('في ٥ علب في كل منها ٦ أقلام. كم قلما في العلب كلها؟'  , '٥ × ٦ = ٣٠ قلما.'                                          , 7),
  ('المتوسط الحسابي للعدد ٤ و ٦ و ٨ يساوي:'               , 'المجموع = ٤ + ٦ + ٨ = ١٨، وعدد القيم ٣، فيكون المتوسط = ٦.', 8),
  ('العدد الذي يلي ٥٠ مباشرة هو:'                         , 'العدد الذي يلي ٥٠ مباشرة هو ٥١.'                           , 9),
  ('العدد الذي يسبق ٤٠ مباشرة هو:'                        , 'العدد الذي يسبق ٤٠ مباشرة هو ٣٩.'                          , 10),
  ('في المتوالية ٢ و ٤ و ٦ و ٨، ما الحد الخامس؟'          , 'المتوالية تزيد ٢ في كل حد، فالحد الخامس هو ١٠.'            , 11),
  ('إذا كان س + ٣ = ٧ فإن قيمة س تساوي:'                  , 'نطرح ٣ من الطرفين: س = ٧ − ٣ = ٤.'                         , 12),
  ('مساحة مربع طول ضلعه ٩ تساوي:'                         , 'مساحة المربع = ٩ × ٩ = ٨١.'                                , 13),
  ('محيط مثلث أطوال أضلاعه ٣ و ٤ و ٥ يساوي:'              , 'محيط المثلث = ٣ + ٤ + ٥ = ١٢.'                             , 14),
  ('محيط مستطيل طوله ٦ وعرضه ٨ يساوي:'                    , 'المحيط = ٢ × (٦ + ٨) = ٢٨.'                                , 15),
  ('عشر في المئة من العدد ٦٠ تساوي:'                      , 'عشر في المئة من ٦٠ = ٦٠ ÷ ١٠ = ٦.'                         , 16),
  ('ثلاثون في المئة من العدد ٢٠٠ تساوي:'                  , '٣٠ في المئة من ٢٠٠ = ٣٠ × ٢٠٠ ÷ ١٠٠ = ٦٠.'                 , 17),
  ('إذا كان ثمن ٣ كتب ١٥ ريالا، فثمن الكتاب الواحد يساوي:', 'نقسم ١٥ على ٣ فيكون الثمن ٥ ريالات للكتاب.'                , 18),
  ('ناتج (١ ÷ ٣) + (١ ÷ ٢) يساوي:'                        , 'ثلث + نصف = ٣/٦ + ١/٦ = ٥/٦.'                              , 19),
  ('أي مما يلي يقسم العدد ٣٦ بالتساوي إلى قسمين متساويين؟', '٣٦ ÷ ٦ = ٦، فالعدد ٦ يقسمه بالتساوي إلى ٦ و ٣٠.'           , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

