-- ---------------------------------------------------------------- العلوم ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'TIMSS' AND s.name = 'العلوم'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('جهاز قياس درجة الحرارة يسمّى:'                                            , 'الميزان الحراري هو جهاز قياس درجة الحرارة.'                                 , 1),
  ('المادة التي لا تسمح بمرور التيار الكهربائي خلالها تسمّى:'                 , 'العازل يمنع مرور التيار، والموصل يسمح بمروره.'                              , 2),
  ('الكوكب المعروف بلونه الأحمر هو:'                                          , 'المريخ هو الكوكب الذي يظهر بلونه الأحمر بسبب أكاسيد الحديد على سطحه.'       , 3),
  ('الحيوان الذي ينام معظم فصل الشتاء في جبال عالية هو:'                      , 'القنفد يدخل في السبات الشتوي في الجبال.'                                    , 4),
  ('البروتين الذي يساهم في تجلط الدم هو:'                                     , 'الليفين بروتين يطلق خيوطه فيساعد على تجلط الدم عند الجرح.'                  , 5),
  ('الهرمون الذي ينظم مستوى السكر في الدم هو:'                                , 'الأنسولين يخفض مستوى السكر في الدم بعد الأكل.'                              , 6),
  ('التفاعل الذي تنطلق فيه حرارة مع الأكسجين يسمّى:'                          , 'الاتحاد مع الأكسجين مع إطلاق حرارة وضوء يسمّى الاحتراق.'                    , 7),
  ('المادة التي تذوب في الماء وتكوّن محلولا تسمّى:'                           , 'الذابة هي المادة التي تذوب في المذيب فتعطي محلولا.'                         , 8),
  ('مثال على الصخور الرسوبية:'                                                , 'الحجر الجيري صخر رسوبي يترسب من جير التربة والماء.'                         , 9),
  ('المصدر الرئيسي للضوء الذي يصل إلى سطح الأرض هو:'                          , 'الشمس هي المصدر الطبيعي للضوء الذي يصل إلى الأرض.'                          , 10),
  ('المادة التي تنقل الحرارة من جسم إلى آخر بسرعة تسمّى:'                     , 'ناقلة الحرارة تنقل الطاقة الحرارية بسرعة، ومن أمثلتها المعادن.'             , 11),
  ('الكثافة لأي جسم تساوي:'                                                   , 'الكثافة = الكتلة ÷ الحجم.'                                                  , 12),
  ('العامل الذي نُبقيه ثابتا أثناء التجربة لاختبار أثر المتغير المستقل يسمّى:', 'العامل الثابت هو الذي يبقى كما هو حتى نعرف أثر المتغير المستقل عليه.'       , 13),
  ('العضو الذي يضخ الدم إلى أنحاء الجسم هو:'                                  , 'القلب عضلة تضخ الدم عبر الأوعية الدموية إلى أنحاء الجسم.'                   , 14),
  ('الكائن الذي يتنفس بالغلاصيم هو:'                                          , 'السمك يتنفس عبر الغلاصيم المغمورة في الماء.'                                , 15),
  ('المستوى الذي يتغير فيه ضغط الهواء بالارتفاع عن سطح الأرض يسمّى:'          , 'الضغط الجوي يقل كلما زاد الارتفاع عن سطح البحر.'                            , 16),
  ('الطاقة التي تحرك الأجسام وتغير من سرعتها تسمّى:'                          , 'الطاقة الحركية هي الطاقة التي تملكها الأجسام بسبب حركتها.'                  , 17),
  ('التغيّر الذي يحوّل الماء من الحالة السائلة إلى صلبة يسمّى:'               , 'التجمد هو تغيّر حالة الماء من سائل إلى صلب عند انخفاض الحرارة.'             , 18),
  ('الكائن الذي ينجذب إلى الضوء فيتحرك نحوه يسمّى:'                           , 'الكائنات التي تتحرّك نحو الضوء تسمّى موجبة الانجذاب للضوء.'                 , 19),
  ('التجويف الذي يصل بالأذن والبلعوم هو:'                                     , 'تجويف الأنف يصل بالأذن والبلعوم، ولهذا تنتقل عدوى الجهاز التنفسي عبر الأنف.', 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

