-- ---------------------------------------------------------------- البيانات ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'TIMSS' AND s.name = 'البيانات'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('درجات ثلاثة طلاب هي ٦ و ٨ و ١٠. ما متوسط هذه الدرجات؟'                            , 'المجموع = ٦ + ٨ + ١٠ = ٢٤، وعدد الطلاب ٣، فيكون المتوسط = ٨.'               , 1),
  ('مجموع خمس قيم هو ٣٠. ما متوسطها؟'                                                 , 'المتوسط = المجموع ÷ عدد القيم = ٣٠ ÷ ٥ = ٦.'                                , 2),
  ('مجموع درجات اختبار في الصف ٣٠٠، وعدد الطلاب ٢٠. ما متوسط الدرجات؟'                , 'المتوسط = ٣٠٠ ÷ ٢٠ = ١٥ درجة.'                                              , 3),
  ('الوسيط للعدد ٢ و ٤ و ٦ و ٨ و ١٠ هو:'                                              , 'بعد ترتيب القيم تصير في الوسط ٦، فهي الوسيط.'                               , 4),
  ('مدى العدد ٣ و ٩ و ٤ يساوي:'                                                       , 'المدى = أكبر قيمة − أصغر قيمة = ٩ − ٣ = ٦.'                                 , 5),
  ('في جدول أعداد الصفوف: ٢ و ٤ و ٦. أي عدد يتكرر أكثر؟'                              , 'العدد ٦ يتكرر مرتين، وهو الأكثر تكرارا في الجدول.'                          , 6),
  ('في جدول أعداد الطلاب في أربعة صفوف: ٢٠ و ٢٢ و ١٨ و ٢٠. كم طالبا في المجموع؟'      , '٢٠ + ٢٢ + ١٨ + ٢٠ = ٨٠ طالبا.'                                              , 7),
  ('نسبة ٤ إلى ٨ في أبسط صورة هي:'                                                    , 'نقسم الطرفين على القاسم المشترك ٤، فتختصر النسبة إلى ١ إلى ٢.'              , 8),
  ('نسبة ٣ إلى ١٢ في أبسط صورة هي:'                                                   , 'نقسم الطرفين على ٣ فيصير الناتج ١ إلى ٤.'                                   , 9),
  ('كم ربعا يساوي نصفا؟'                                                              , 'النصف = ربعان، أي ٢ × ١/٤.'                                                 , 10),
  ('المحور الرأسي في الرسم البياني يمثّل عادة:'                                       , 'المحور الرأسي يمثّل القيم التي نقيسها، والمحور الأفقي يمثّل الفئات.'        , 11),
  ('في جدول تكرارات مجموعه ٢٠، الفئة تكرارها ٥. ما تكرارها النسبي؟'                   , 'التكرار النسبي = ٥ ÷ ٢٠ = ربع.'                                             , 12),
  ('إذا ضوعفت كل قيم جدول، فإن متوسطه:'                                               , 'ضرب كل قيمة في ٢ يضرب المتوسط في ٢، فيتضاعف المتوسط.'                       , 13),
  ('الفرق بين أكبر قيمة وأصغر قيمة في مجموعة بيانات يسمّى:'                           , 'المدى هو الفرق بين أكبر قيمة وأصغر قيمة.'                                   , 14),
  ('في جدول: ٣ و ٦ و ٩. ما النمط في هذه القيم؟'                                       , 'كل قيمة تزيد عن سابقتها ٣، وهذا نمط زيادة ثابتة.'                           , 15),
  ('عند قراءة جدول، يجب أن نبدأ بـ:'                                                  , 'البداية الصحيحة بقراءة عنوان الجدول والتعريف بأعمدته قبل قراءة الأرقام.'    , 16),
  ('انخفض عدد الحضور من ٤٠ إلى ٣٠. نسبة النقص إلى الأصل تساوي:'                       , 'النقص = ٤٠ − ٣٠ = ١٠، والنسبة إلى الأصل = ١٠ ÷ ٤٠ = ربع.'                   , 17),
  ('قيمة المدى لمجموعة ٢ و ٧ و ٤ و ٩ تساوي:'                                          , 'أصغر قيمة ٢ وأكبرها ٩، فيكون المدى = ٩ − ٢ = ٧.'                            , 18),
  ('متوسط درجات طالب في ثلاث مواد هو ٨٠. إذا كانت درجتان ٧٠ و ٨٠، فما الدرجة الثالثة؟', 'مجموع الدرجات = ٨٠ × ٣ = ٢٤٠، والدرجتان المعروفتان تساويان ١٥٠، فالباقي ٩٠.', 19),
  ('أي مما يلي يمثل سؤالا إحصائيا يعتمد على البيانات؟'                                , 'السؤال الإحصائي يطلب عددا أو نسبة من بيانات، مثل: كم طالبا في المجموعة؟'    , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

