);

-- ---------------------------------------------------------------- الدراسة ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'TIMSS' AND s.name = 'الدراسة'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('أفضل طريقة لتثبيت المعلومة على المدى الطويل هي:' , 'تكرار المراجعة على فترات متباعدة يثبّت المعلومة أكثر من حشرها دفعة واحدة.'               , 1),
  ('الهدف من حل أسئلة الاختبارات السابقة هو:'        , 'حل الاختبارات السابقة يكشف نقاط الضعف ويعرفك على نمط الأسئلة والزمن المطلوب.'            , 2),
  ('رسم خريطة ذهنية للدرس يساعد على:'                , 'الخريطة الذهنية تنظم العلاقات بين المفاهيم وتسهّل استرجاعها.'                            , 3),
  ('إذا قرأت فقرة ولم تفهمها، فإن الخطوة الصحيحة هي:', 'الرجوع وقراءة الفقرة مرة ثانية بتمعّن، ثم تحديد موضع الصعوبة وطلب المساعدة.'             , 4),
  ('تنظيم وقت المذاكرة يكون أكثر فعالية عند:'        , 'خطة زمنية محددة تجعل لكل مادة وقتا معلوما وتقلل التسويف.'                                , 5),
  ('طريقة الاسترجاع في المذاكرة تعني:'               , 'الاسترجاع محاولة استدعاء المعلومة من الذاكرة دون النظر إليها، وهي أقوى من إعادة القراءة.', 6),
  ('الهدف الرئيسي من التلخيص هو:'                    , 'التلخيص يعبّر عن الأفكار الرئيسة بكلماتك أنت، ويكشف ما لم تفهمه بعد.'                    , 7),
  ('الاستماع دون تركيز أثناء الدرس:'                 , 'الاستماع السلبي دون تركيز يمر دون أثر، والمشاركة والتلخيص هما ما يثبّت المعلومة.'        , 8),
  ('المذاكرة الجماعية المفيدة تحتاج إلى:'            , 'المذاكرة الجماعية تنفع إذا كان هناك هدف واضح وشرح متبادل، لا مجرد وجود.'                 , 9),
  ('التخطيط الجيد للاختبار يبدأ بـ:'                 , 'البداية بجمع المعلومات عن الاختبار: عدد الأسئلة، الزمن، والمواد المشمولة.'               , 10),
  ('كتابة أسئلة أثناء المذاكرة تفيد لأنها:'          , 'كتابة الأسئلة تجعلك تسترجع المعلومات وتكتشف الفجوات قبل الاختبار.'                       , 11),
  ('تكرار قراءة الصفحة عدة مرات وحدها:'              , 'إعادة القراءة وحدها تعطي شعورا كاذبا بالفهم، والاسترجاع أعظم أثرا منها.'                 , 12),
  ('أفضل مكان للمذاكرة هو المكان الذي:'              , 'المكان الهادئ والمريح يقلل المشتتات ويحافظ على التركيز.'                                 , 13),
  ('عند الخطأ في حل مسألة، الأفضل أن:'               , 'الخطأ في حل مسألة يبيّن سبب الالتباس، وفهمه يمنع تكراره.'                                , 14),
  ('تقسيم الدرس الكبير إلى أجزاء صغيرة يفيد لأن:'    , 'تقسيم المادة يجعل الهدف واضحا ويسهل متابعة الإنجاز ويقلل الترهيب.'                       , 15),
  ('الاختبار الذاتي هو أن:'                          , 'الاختبار الذاتي أن تحاول الإجابة من ذاكرتك ثم تقارن بالإجابة الصحيحة.'                   , 16),
  ('توزيع المذاكرة على أيام كثيرة أفضل من:'          , 'توزيع الجهد على أيام متعددة يثبّت المعلومة أكثر من حصرها في يوم واحد.'                   , 17),
  ('مراجعة الملاحظات النهائية قبل الاختبار مباشرة:'  , 'المراجعة النهائية للملخص لا تنفع إذا لم يفهم الطالب الأساس من قبل.'                      , 18),
  ('رتّب خطوات الإجابة عن سؤال اختبار:'              , 'الترتيب الصحيح: أقرأ السؤال، أحدد المطلوب، أختار الإجابة، ثم أتحقق منها.'                , 19),
  ('أهم ما يفعله الطالب قبل الاختبار مباشرة:'        , 'المراجعة النهائية مهمة، لكن الأساس يبقى الفهم لا الحفظ السريع في الساعات الأخيرة.'       , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

