  ('أفضل مكان للمذاكرة هو المكان الذي:'              , 'فيه ضجيج وأصوات عالية'                  , false, 13),
  ('عند الخطأ في حل مسألة، الأفضل أن:'               , 'نلوم المعلم على الخطأ'                  , false, 14),
  ('عند الخطأ في حل مسألة، الأفضل أن:'               , 'ننسى المسألة كأنها لم تكن'              , false, 14),
  ('عند الخطأ في حل مسألة، الأفضل أن:'               , 'نراجع سبب الخطأ حتى لا يتكرر'           , true , 14),
  ('عند الخطأ في حل مسألة، الأفضل أن:'               , 'ننتقل إلى مادة أخرى فورا'               , false, 14),
  ('تقسيم الدرس الكبير إلى أجزاء صغيرة يفيد لأن:'    , 'يلغي الحاجة إلى المراجعة'               , false, 15),
  ('تقسيم الدرس الكبير إلى أجزاء صغيرة يفيد لأن:'    , 'يقلل عدد المواضيع المطلوبة'             , false, 15),
  ('تقسيم الدرس الكبير إلى أجزاء صغيرة يفيد لأن:'    , 'يخلو المذاكرة من أي ترهيب'              , false, 15),
  ('تقسيم الدرس الكبير إلى أجزاء صغيرة يفيد لأن:'    , 'يجعل الهدف أوضح وأسهل في الإنجاز'       , true , 15),
  ('الاختبار الذاتي هو أن:'                          , 'تمتحن نفسك دون مرجع'                    , true , 16),
  ('الاختبار الذاتي هو أن:'                          , 'تختبر زملاءك'                           , false, 16),
  ('الاختبار الذاتي هو أن:'                          , 'تعيد قراءة الملخص'                      , false, 16),
  ('الاختبار الذاتي هو أن:'                          , 'تسأل المعلم عن الدرجة'                  , false, 16),
  ('توزيع المذاكرة على أيام كثيرة أفضل من:'          , 'توزيعها على أيام متعددة'                , false, 17),
  ('توزيع المذاكرة على أيام كثيرة أفضل من:'          , 'حصرها في يوم واحد قبل الاختبار'         , true , 17),
  ('توزيع المذاكرة على أيام كثيرة أفضل من:'          , 'مذاكرة اثنتين منها فقط'                 , false, 17),
  ('توزيع المذاكرة على أيام كثيرة أفضل من:'          , 'المذاكرة في مكان هادئ'                  , false, 17),
  ('مراجعة الملاحظات النهائية قبل الاختبار مباشرة:'  , 'غير مفيدة في أي حالة'                   , false, 18),
  ('مراجعة الملاحظات النهائية قبل الاختبار مباشرة:'  , 'مفيدة لكل المواد دون استثناء'           , false, 18),
  ('مراجعة الملاحظات النهائية قبل الاختبار مباشرة:'  , 'مفيدة إذا سبقتك المذاكرة الكاملة'       , true , 18),
  ('مراجعة الملاحظات النهائية قبل الاختبار مباشرة:'  , 'تكفي وحدها لإتقان المنهج'               , false, 18),
  ('رتّب خطوات الإجابة عن سؤال اختبار:'              , 'أختار ثم أقرأ ثم أتحقق ثم أحدد المطلوب' , false, 19),
  ('رتّب خطوات الإجابة عن سؤال اختبار:'              , 'أحدد المطلوب ثم أتحقق ثم أقرأ ثم أختار' , false, 19),
  ('رتّب خطوات الإجابة عن سؤال اختبار:'              , 'أتحقق ثم أختار ثم أحدد المطلوب ثم أقرأ' , false, 19),
  ('رتّب خطوات الإجابة عن سؤال اختبار:'              , 'أقرأ ثم أحدد المطلوب ثم أختار ثم أتحقق' , true , 19),
  ('أهم ما يفعله الطالب قبل الاختبار مباشرة:'        , 'يراجع ثم ينام مبكرا'                    , true , 20),
  ('أهم ما يفعله الطالب قبل الاختبار مباشرة:'        , 'يحفظ كل صفحة في آخر لحظة'               , false, 20),
  ('أهم ما يفعله الطالب قبل الاختبار مباشرة:'        , 'ينام قليلا فقط'                         , false, 20),
  ('أهم ما يفعله الطالب قبل الاختبار مباشرة:'        , 'يعتمد على مراجعة سريعة دون فهم'         , false, 20)
) AS v(qcontent, content, correct, ord)
JOIN questions q
  ON q.content = v.qcontent
  AND q.section_id = (
    SELECT s.id FROM sections s
    JOIN exam_types et ON et.id = s.exam_type_id
    WHERE et.code = 'TIMSS' AND s.name = 'الدراسة'
  )
WHERE NOT EXISTS (
  SELECT 1 FROM choices c WHERE c.question_id = q.id AND c.content = v.content
);

-- ---------------------------------------------------------------- القراءة ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'TIMSS' AND s.name = 'القراءة'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('اقرأ: (تستقبل مكتبة المدرسة الزوار. ومن بين أقسامها قسم مخصص للكتب التي تنفع جميع الأعمار، وقسم آخر للكتب التي تترجم إلى لغات كثيرة). الفكرة الرئيسة في الفقرة:', 'الحديث عن أقسام المكتبة، والفكرة الرئيسة هي خدمتها لجميع الأعمار واللغات.'                   , 1),
  ('اقرأ: (نشر خالد إعلانا صغيرا عن محفظة وجدها قرب ملعب المدرسة. وأعادها إلى إدارة المدرسة بعد أسبوع). لماذا فعل خالد ما فعل؟'                                     , 'أعاد خالد المحفظة إلى إدارة المدرسة لأنه أراد أن يتصرف بأمانة.'                              , 2),
  ('اقرأ: (تحتاج النباتات إلى ضوء الشمس في تصنع غذاءها. وفي الظلام الدامس يزهر النبات ويموت). العلاقة بين الشمس والنبات حسب النص:'                                  , 'الشمس هي مصدر غذاء النبات، وبدونها يذبل ويموت.'                                              , 3),
  ('اقرأ: (يمكن لكل بيت أن يقلل نفاياته بفرز الزجاج والورق والبلاستيك في صناديق مخصّصة، بدل رميها كلها). المقصود ب(فرز النفايات):'                                  , 'الفرز يعني فصل النفايات إلى أنواعها لإعادة استخدام كل نوع.'                                  , 4),
  ('اقرأ: (الطريق من الحي إلى المدرسة تقطعه الحافلة في ١٠ دقائق، بينما يستغرق سيرا ٣٠ دقيقة. والحافلة أرخص وأقل تلويثا). نصيحة الكاتب:'                             , 'النص يقارن بين الحافلة والسير ويوصي باستخدام الوسيلة الأقل تلويثا.'                          , 5),
  ('اقرأ: (الترشيد يعني أن نستعمل ما نملكه بقدر حاجتنا، فلا نسرف في الماء ولا في الكهرباء ولا في الطعام). معنى كلمة(الترشيد):'                                      , 'الترشيد هو الاستعمال المعتدل للموارد بلا إسراف ولا هدر.'                                     , 6),
  ('العبارة(ينتج عن إهمالنا تلويث الأنهار) تدل على نوع من العلاقات، هو:'                                                                                            , 'كلمة(ينتج عن) تربط بين سبب ونتيجة، فالإهمال سبب والتلويث نتيجة.'                             , 7),
  ('اقرأ: (القراءة السريعة تفيد في معرفة الفكرة العامة. أما القراءة المركزة فتجعلك تفهم التفاصيل، وتبقي انتباهك في الموضع). الرأي الذي يتبناه الكاتب:'              , 'الكاتب يفضل القراءة المركزة على القراءة السريعة في فهم التفاصيل.'                            , 8),
  ('في نص علمي، يكون ترتيب الأفكار غالبا هكذا:'                                                                                                                     , 'الترتيب المعتاد في النص العلمي: تعريف، ثم تفسير، ثم دليل، ثم خاتمة.'                         , 9),
  ('اقرأ: (قال الكاتب: ماهر حق من يرمي الفضلات في الأرض ثم يتظاهر بغيره). المعنى المقصود ب(ماهر حق):'                                                               , 'ماهر حق أي محتال ظالم، والنص ينتقد من يتظاهر بالشرف وهو ليس به.'                             , 10),
  ('يبيّن الكاتب أن يفهم من خلال نصه كل من يريد أن يقنع الناس، فيعتمد على:'                                                                                         , 'النص يجمع بين المعلومات والأرقام والأمثلة، وهذا ينفع من يريد الإقناع والتعليم.'              , 11),
  ('اقرأ: (الكتابة الجيدة تحتاج إلى قراءة جيدة أولا، لأن الكاتب يستمد أفكاره وما ينتبه إليه من قراءته). العلاقة بين القراءة الجيدة والكتابة الجيدة:'                , 'الكتابة الجيدة تحتاج قراءة جيدة أولا، فالقراءة تغذي الكتابة.'                                , 12),
  ('الشيء الذي يعترض عليه الكاتب هو:'                                                                                                                               , 'يعترض على من يكتفني بالمظهر دون جوهر.'                                                       , 13),
  ('ما المقصود ب(غير الصالح للشرب)؟'                                                                                                                                , 'غير الصالح للشرب يعني الماء غير الآمن للاستخدام في الشرب.'                                   , 14),
  ('اقرأ: (خمسون في المئة من المياه في زماننا مهدورة، بسبب ضياعها في المصارف والرشّ). معنى كلمة(مهدورة):'                                                           , 'مهدورة أي ضائعة بلا استفادة ولا عودة إلى الاستخدام.'                                         , 15),
  ('عنوان مناسب لنص يتكلم عن محفظة عثر عليها طالب وأعادها إلى صاحبها:'                                                                                              , 'العنوان يصف الفكرة الرئيسة: محفظة تعود إلى صاحبها.'                                          , 16),
  ('ما هو الغرض من الفقرة الأولى من أي نص علمي؟'                                                                                                                    , 'الغرض من الفقرة الأولى تقديم الخلفية والتعريف بالموضوع قبل الدخول في التفاصيل.'              , 17),
  ('بعد قراءة النص نكون على يقين بأن:'                                                                                                                              , 'النص يقيم الحقائق بالأرقام والأمثلة، فيبيّن أن المعلومة التي يقتنع بها الناس تحتاج إلى دليل.', 18),
  ('الكلمة(النقض) في سياق نص علمي تعني:'                                                                                                                            , 'النقض هو الشيء المضاد للشيء الذي نتكلم عنه.'                                                 , 19),
  ('اقرأ: (كتب أحمد دفتره ليسجل فيه ما يفكر فيه كل يوم. وبعد شهر عاد وقرأ ما كتب، فوجد أن أفكاره تغيرت وفيها أخطاء كثيرة). فائدة تدوين الأفكار:'                    , 'تدوين الأفكار ثم مراجعته يكشف أخطاءه ويبيّن له تطوّر أفكاره.'                                , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

INSERT INTO choices (id, content, is_correct, question_id)
