  ('اقرأ: (الطريق من الحي إلى المدرسة تقطعه الحافلة في ١٠ دقائق، بينما يستغرق سيرا ٣٠ دقيقة. والحافلة أرخص وأقل تلويثا). نصيحة الكاتب:'                             , 'عدم الذهاب إلى المدرسة'                      , false, 5),
  ('اقرأ: (الترشيد يعني أن نستعمل ما نملكه بقدر حاجتنا، فلا نسرف في الماء ولا في الكهرباء ولا في الطعام). معنى كلمة(الترشيد):'                                      , 'زيادة الإنتاج دائمًا'                        , false, 6),
  ('اقرأ: (الترشيد يعني أن نستعمل ما نملكه بقدر حاجتنا، فلا نسرف في الماء ولا في الكهرباء ولا في الطعام). معنى كلمة(الترشيد):'                                      , 'الاستعمال المعتدل للموارد بلا إسراف'         , true , 6),
  ('اقرأ: (الترشيد يعني أن نستعمل ما نملكه بقدر حاجتنا، فلا نسرف في الماء ولا في الكهرباء ولا في الطعام). معنى كلمة(الترشيد):'                                      , 'الإسراف في الاستهلاك'                        , false, 6),
  ('اقرأ: (الترشيد يعني أن نستعمل ما نملكه بقدر حاجتنا، فلا نسرف في الماء ولا في الكهرباء ولا في الطعام). معنى كلمة(الترشيد):'                                      , 'منع الفرد من الاستعمال'                      , false, 6),
  ('العبارة(ينتج عن إهمالنا تلويث الأنهار) تدل على نوع من العلاقات، هو:'                                                                                            , 'علاقة تضاد بين الأمرين'                      , false, 7),
  ('العبارة(ينتج عن إهمالنا تلويث الأنهار) تدل على نوع من العلاقات، هو:'                                                                                            , 'علاقة تضامن بين الأمرين'                     , false, 7),
  ('العبارة(ينتج عن إهمالنا تلويث الأنهار) تدل على نوع من العلاقات، هو:'                                                                                            , 'علاقة سببية بين الإهمال والتلويث'            , true , 7),
