) AS v(qcontent, content, correct, ord)
JOIN questions q
  ON q.content = v.qcontent
  AND q.section_id = (
    SELECT s.id FROM sections s
    JOIN exam_types et ON et.id = s.exam_type_id
    WHERE et.code = 'TIMSS' AND s.name = 'القراءة'
  )
WHERE NOT EXISTS (
  SELECT 1 FROM choices c WHERE c.question_id = q.id AND c.content = v.content
);

-- ----------------------------------------------------------------------------
-- VERIFY
-- ----------------------------------------------------------------------------
SELECT 'exam_types'  AS entity, count(*) FROM exam_types  WHERE code = 'TIMSS'
UNION ALL SELECT 'sections',   count(*) FROM sections s JOIN exam_types et ON et.id = s.exam_type_id WHERE et.code = 'TIMSS'
UNION ALL SELECT 'questions',  count(*) FROM questions q JOIN sections s ON s.id = q.section_id JOIN exam_types et ON et.id = s.exam_type_id WHERE et.code = 'TIMSS'
UNION ALL SELECT 'choices',    count(*) FROM choices ch JOIN questions q ON q.id = ch.question_id JOIN sections s ON s.id = q.section_id JOIN exam_types et ON et.id = s.exam_type_id WHERE et.code = 'TIMSS';

COMMIT;
